# Byte-preserving handoff to the calling shell; graphics remain generated by R.
source('D:/project/tangjie/trace_as_state_repro/paper/draw_confirmation_composite_20261014.R')
for(name in c('publication_v3.png','preview_v3.png','publication_v3.pdf','graph_means.csv','plot_arms.csv','plot_contrasts.csv','PROVENANCE.txt')) {
 con<-file(file.path(out,name),'rb');bytes<-raw()
 repeat { chunk<-readBin(con,'raw',n=1048576);if(!length(chunk))break;bytes<-c(bytes,chunk) }
 close(con)
 cat('FIG_EXPORT|',name,'|',paste(sprintf('%02x',as.integer(bytes)),collapse=''),'\n',sep='')
}
